package android.content.pm;import android.content.*;import java.util.*;public class PackageManager{public static final int MATCH_DEFAULT_ONLY=1,PERMISSION_GRANTED=0;public long packageVersion=1;public List<ApplicationInfo> installed=new ArrayList<>();public List<ApplicationInfo> getInstalledApplications(int flags){return installed;}public CharSequence getApplicationLabel(ApplicationInfo i){return "测试应用";}public PackageInfo getPackageInfo(String p,int f)throws NameNotFoundException{PackageInfo i=new PackageInfo();i.version=packageVersion;return i;}public static class NameNotFoundException extends Exception{}public List<ResolveInfo> queryIntentActivities(Intent i,int f){return Collections.emptyList();}public ActivityInfo getActivityInfo(ComponentName n,int f)throws NameNotFoundException{return new ActivityInfo();}public ApplicationInfo getApplicationInfo(String p,int f)throws NameNotFoundException{return new ApplicationInfo();}}